const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Punjab and Haryana geometry (approximate bounding box)
  const punjabHaryana = ee.Geometry.Rectangle([73.5, 29.0, 77.5, 32.5]);

  try {
    // Try VIIRS fire collection
    let fireColl = ee.ImageCollection('FIRMS');

    // Check if collection exists and has data
    let testSize = fireColl.filterBounds(punjabHaryana).filterDate('2024-11-01', '2024-11-30').size().getInfo();

    if (testSize === 0) {
      // Fallback to MODIS if FIRMS unavailable
      fireColl = ee.ImageCollection('MODIS/006/MOD14A1');
      testSize = fireColl.filterBounds(punjabHaryana).filterDate('2024-11-01', '2024-11-30').size().getInfo();
    }

    if (testSize === 0) {
      print("No fire data found for region in Nov 2024");
      print("<answer>C1</answer>");
      return;
    }

    // Count fires for each November 2012-2023 and 2024
    const fireCountsByYear = {};
    const years = Array.from({length: 12}, (_, i) => 2012 + i).concat([2024]);

    for (const year of years) {
      const startDate = `${year}-11-01`;
      const endDate = `${year}-12-01`;

      const col = fireColl
        .filterBounds(punjabHaryana)
        .filterDate(startDate, endDate)
        .map(img => img.select('confidence'));

      // Count fire detections (confidence > 50)
      const fireCount = col
        .map(img => {
          const mask = img.gt(50);
          return mask.reduceRegion(
            {reducer: ee.Reducer.sum(), geometry: punjabHaryana, scale: 1000, maxPixels: 1e9}
          ).get('confidence');
        })
        .reduceList(ee.Reducer.sum(), false)
        .getInfo();

      fireCountsByYear[year] = fireCount || 0;
      print(`Nov ${year}: ${fireCountsByYear[year]} fires`);
    }

    const nov2024Count = fireCountsByYear[2024];
    const historicalCounts = years.slice(0, -1).map(y => fireCountsByYear[y]);

    // Check if Nov 2024 is lower than ALL other Novembers
    const isLowestOrEqual = historicalCounts.every(count => nov2024Count < count);

    print(`Nov 2024 count: ${nov2024Count}`);
    print(`Historical min: ${Math.min(...historicalCounts)}`);

    if (isLowestOrEqual) {
      print("<answer>A</answer>");
    } else {
      print("<answer>B</answer>");
    }

  } catch (error) {
    print(`Error: ${error.message}`);
    print("<answer>D</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
